# =============================================================================
# XML SERIES SEARCH
# =============================================================================

def find_xml_for_series(series_uid):

    target = str(
        series_uid
    ).strip()

    matches = []

    xml_files = glob.glob(
        os.path.join(
            XML_DIR,
            "**",
            "*.xml"
        ),
        recursive=True
    )

    for xml_path in xml_files:

        try:

            tree = ET.parse(xml_path)
            root = tree.getroot()

            found_uid = None

            for elem in root.iter():

                tag = elem.tag.split("}")[-1]

                if tag.lower() == "seriesinstanceuid":

                    if elem.text:

                        found_uid = (
                            elem.text.strip()
                        )

                        break

            if found_uid == target:

                matches.append(
                    xml_path
                )

        except Exception:

            continue

    return matches


# =============================================================================
# XML NODULE PARSER
# =============================================================================

def parse_xml_nodules(xml_path):

    tree = ET.parse(
        xml_path
    )

    root = tree.getroot()

    result = []

    for xml_index, node in enumerate(
        root.iter()
    ):

        tag = node.tag.split("}")[-1]

        if tag != "unblindedReadNodule":

            continue

        # -------------------------------------------------------------
        # Nodule ID
        # -------------------------------------------------------------

        xml_id = f"XML_{xml_index}"

        for child in node:

            child_tag = child.tag.split("}")[-1]

            if child_tag == "noduleID":

                if child.text:

                    xml_id = (
                        child.text.strip()
                    )

                break

        # -------------------------------------------------------------
        # Malignancy
        # -------------------------------------------------------------

        malignancy = None

        for elem in node.iter():

            elem_tag = elem.tag.split("}")[-1]

            if elem_tag == "malignancy":

                if elem.text:

                    try:

                        malignancy = int(
                            elem.text.strip()
                        )

                    except Exception:

                        malignancy = None

                break

        # -------------------------------------------------------------
        # ROIs
        # -------------------------------------------------------------

        rois = []

        for roi in node.iter():

            roi_tag = roi.tag.split("}")[-1]

            if roi_tag != "roi":

                continue

            z = None
            sop = ""

            for child in roi:

                child_tag = child.tag.split("}")[-1]

                if child_tag == "imageZposition":

                    if child.text:

                        try:

                            z = float(
                                child.text.strip()
                            )

                        except Exception:

                            z = None

                elif child_tag == "imageSOP_UID":

                    if child.text:

                        sop = (
                            child.text.strip()
                        )

            xs = []
            ys = []

            for edge in roi.iter():

                edge_tag = edge.tag.split("}")[-1]

                if edge_tag != "edgeMap":

                    continue

                x_val = None
                y_val = None

                for child in edge:

                    child_tag = child.tag.split("}")[-1]

                    if (
                        child_tag == "xCoord"
                        and child.text
                    ):

                        try:

                            x_val = float(
                                child.text.strip()
                            )

                        except Exception:

                            pass

                    elif (
                        child_tag == "yCoord"
                        and child.text
                    ):

                        try:

                            y_val = float(
                                child.text.strip()
                            )

                        except Exception:

                            pass

                if (
                    x_val is not None
                    and y_val is not None
                ):

                    xs.append(
                        x_val
                    )

                    ys.append(
                        y_val
                    )

            if (
                z is not None
                and len(xs) >= 3
            ):

                rois.append({

                    "z": z,

                    "sop": sop,

                    "xs": xs,

                    "ys": ys,

                    "cx": float(
                        np.mean(xs)
                    ),

                    "cy": float(
                        np.mean(ys)
                    )

                })

        rois.sort(
            key=lambda r: r["z"]
        )

        result.append({

            "xml_nodule_id":
                xml_id,

            "xml_index":
                xml_index,

            "malignancy":
                malignancy,

            "rois":
                rois

        })

    return result


# =============================================================================
# NATIVE MASK READER
# =============================================================================

def read_native_masks(
    zf,
    patient_id,
    native_id
):

    base = (
        f"LIDC-IDRI-slices/"
        f"{patient_id}/"
        f"{native_id}/"
    )

    names = zf.namelist()

    output = {}

    for mask_number in range(4):

        prefix = (
            f"{base}mask-{mask_number}/"
        )

        files = sorted([
            name
            for name in names
            if (
                name.startswith(prefix)
                and name.lower().endswith(".png")
            )
        ])

        slices = []

        for filename in files:

            try:

                with zf.open(
                    filename
                ) as f:

                    arr = np.array(
                        Image.open(
                            io.BytesIO(
                                f.read()
                            )
                        ).convert("L")
                    ) > 0

                if arr.sum() == 0:
                    continue

                ys, xs = np.where(arr)

                slices.append({

                    "filename":
                        filename,

                    "array":
                        arr,

                    "cx":
                        float(xs.mean()),

                    "cy":
                        float(ys.mean())

                })

            except Exception:

                pass

        output[mask_number] = slices

    return output


# =============================================================================
# RASTERIZE XML POLYGON
# =============================================================================

def rasterize_polygon(
    xs,
    ys,
    shape,
    dx,
    dy
):

    height, width = shape

    translated_x = (
        np.asarray(xs)
        + dx
    )

    translated_y = (
        np.asarray(ys)
        + dy
    )

    polygon = np.column_stack([
        translated_x,
        translated_y
    ])

    path = Path(
        polygon
    )

    yy, xx = np.meshgrid(
        np.arange(height),
        np.arange(width),
        indexing="ij"
    )

    points = np.column_stack([
        xx.ravel(),
        yy.ravel()
    ])

    raster = path.contains_points(
        points
    ).reshape(
        height,
        width
    )

    return raster


# =============================================================================
# COMPARE NATIVE MASK TO XML NODULE
# =============================================================================

def compare_mask_to_xml(
    native_slices,
    xml_rois
):

    if (
        len(native_slices) == 0
        or len(xml_rois) == 0
    ):

        return None

    best_result = None

    n_native = len(native_slices)
    n_xml = len(xml_rois)

    max_offset = max(
        0,
        n_native - n_xml
    )

    for offset in range(
        max_offset + 1
    ):

        usable = min(
            n_xml,
            n_native - offset
        )

        if usable <= 0:
            continue

        native_part = (
            native_slices[
                offset:
                offset + usable
            ]
        )

        xml_part = (
            xml_rois[
                :usable
            ]
        )

        native_cx = np.mean([
            s["cx"]
            for s in native_part
        ])

        native_cy = np.mean([
            s["cy"]
            for s in native_part
        ])

        xml_cx = np.mean([
            r["cx"]
            for r in xml_part
        ])

        xml_cy = np.mean([
            r["cy"]
            for r in xml_part
        ])

        base_dx = (
            native_cx
            - xml_cx
        )

        base_dy = (
            native_cy
            - xml_cy
        )

        dx_values = np.arange(
            base_dx - 4,
            base_dx + 4.1,
            1.0
        )

        dy_values = np.arange(
            base_dy - 4,
            base_dy + 4.1,
            1.0
        )

        for dx in dx_values:

            for dy in dy_values:

                dice_values = []
                iou_values = []

                for i in range(
                    usable
                ):

                    native = native_part[i]
                    xml = xml_part[i]

                    xml_mask = (
                        rasterize_polygon(
                            xml["xs"],
                            xml["ys"],
                            native["array"].shape,
                            dx,
                            dy
                        )
                    )

                    native_mask = (
                        native["array"]
                    )

                    intersection = np.logical_and(
                        native_mask,
                        xml_mask
                    ).sum()

                    union = np.logical_or(
                        native_mask,
                        xml_mask
                    ).sum()

                    denominator = (
                        native_mask.sum()
                        + xml_mask.sum()
                    )

                    dice = (
                        2.0 * intersection
                        / denominator
                        if denominator > 0
                        else 0.0
                    )

                    iou = (
                        intersection
                        / union
                        if union > 0
                        else 0.0
                    )

                    dice_values.append(
                        dice
                    )

                    iou_values.append(
                        iou
                    )

                mean_dice = float(
                    np.mean(
                        dice_values
                    )
                )

                mean_iou = float(
                    np.mean(
                        iou_values
                    )
                )

                candidate = {

                    "mean_dice":
                        mean_dice,

                    "mean_iou":
                        mean_iou,

                    "dx":
                        float(dx),

                    "dy":
                        float(dy),

                    "z_offset":
                        int(offset),

                    "matched_slices":
                        int(usable)

                }

                if (
                    best_result is None
                    or candidate["mean_dice"]
                    > best_result["mean_dice"]
                ):

                    best_result = candidate

    return best_result


# =============================================================================
# RUN AUDIT
# =============================================================================

audit_rows = []

print("\n" + "=" * 80)
print("RUNNING FORENSIC COMPARISONS")
print("=" * 80)

with zipfile.ZipFile(
    ZIP_PATH,
    "r"
) as zf:

    for case_number, (_, row) in enumerate(
        promising_std.iterrows(),
        start=1
    ):

        subset_id = row[
            "subset_nodule_id"
        ]

        patient_id = row[
            "patient_id"
        ]

        native_id = row[
            "native_nodule_id"
        ]

        series_uid = row[
            "SeriesInstanceUID"
        ]

        print(
            f"\n[{case_number}/"
            f"{len(promising_std)}] "
            f"{subset_id}"
        )

        # -------------------------------------------------------------
        # Find XML
        # -------------------------------------------------------------

        xml_files = find_xml_for_series(
            series_uid
        )

        if not xml_files:

            print(
                "  XML: NOT FOUND"
            )

            audit_rows.append({

                "subset_nodule_id":
                    subset_id,

                "patient_id":
                    patient_id,

                "native_nodule_id":
                    native_id,

                "SeriesInstanceUID":
                    series_uid,

                "audit_status":
                    "NO_XML"

            })

            continue

        xml_path = xml_files[0]

        print(
            f"  XML: "
            f"{os.path.basename(xml_path)}"
        )

        # -------------------------------------------------------------
        # Parse XML
        # -------------------------------------------------------------

        xml_nodules = parse_xml_nodules(
            xml_path
        )

        print(
            f"  XML nodules: "
            f"{len(xml_nodules)}"
        )

        # -------------------------------------------------------------
        # Read native masks
        # -------------------------------------------------------------

        native_masks = read_native_masks(
            zf,
            patient_id,
            native_id
        )

        # -------------------------------------------------------------
        # Compare every mask against every XML nodule
        # -------------------------------------------------------------

        for mask_number, native_slices in native_masks.items():

            if not native_slices:
                continue

            for xnod in xml_nodules:

                comparison = compare_mask_to_xml(
                    native_slices,
                    xnod["rois"]
                )

                if comparison is None:
                    continue

                audit_rows.append({

                    "subset_nodule_id":
                        subset_id,

                    "patient_id":
                        patient_id,

                    "native_nodule_id":
                        native_id,

                    "SeriesInstanceUID":
                        series_uid,

                    "xml_file":
                        os.path.basename(
                            xml_path
                        ),

                    "native_mask":
                        f"mask-{mask_number}",

                    "xml_nodule_id":
                        xnod[
                            "xml_nodule_id"
                        ],

                    "xml_index":
                        xnod[
                            "xml_index"
                        ],

                    "xml_malignancy":
                        xnod[
                            "malignancy"
                        ],

                    "native_active_slices":
                        len(native_slices),

                    "xml_roi_count":
                        len(xnod["rois"]),

                    "matched_slices":
                        comparison[
                            "matched_slices"
                        ],

                    "z_offset":
                        comparison[
                            "z_offset"
                        ],

                    "dx":
                        round(
                            comparison["dx"],
                            3
                        ),

                    "dy":
                        round(
                            comparison["dy"],
                            3
                        ),

                    "mean_Dice":
                        round(
                            comparison["mean_dice"],
                            5
                        ),

                    "mean_IoU":
                        round(
                            comparison["mean_iou"],
                            5
                        ),

                    "audit_status":
                        "GEOMETRIC_EVIDENCE_ONLY"

                })


# =============================================================================
# SAVE DETAILED AUDIT
# =============================================================================

audit_df = pd.DataFrame(
    audit_rows
)

audit_df.to_csv(
    OUT_CSV,
    index=False
)


# =============================================================================
# SELECT BEST CANDIDATE PER NATIVE NODULE
# =============================================================================

best_rows = []

if not audit_df.empty:

    for subset_id, group in audit_df.groupby(
        "subset_nodule_id"
    ):

        group = group.sort_values(
            "mean_Dice",
            ascending=False
        ).reset_index(
            drop=True
        )

        best = group.iloc[0]

        if len(group) > 1:
            second = group.iloc[1]

            second_score = float(
                second["mean_Dice"]
            )

            margin = (
                float(best["mean_Dice"])
                - second_score
            )

        else:

            second_score = np.nan
            margin = np.nan

        best_rows.append({

            "subset_nodule_id":
                subset_id,

            "patient_id":
                best["patient_id"],

            "native_nodule_id":
                best["native_nodule_id"],

            "best_native_mask":
                best["native_mask"],

            "best_xml_nodule_id":
                best["xml_nodule_id"],

            "xml_malignancy":
                best["xml_malignancy"],

            "best_mean_Dice":
                float(best["mean_Dice"]),

            "second_best_mean_Dice":
                second_score,

            "Dice_margin":
                margin,

            "best_mean_IoU":
                float(best["mean_IoU"]),

            "matched_slices":
                int(best["matched_slices"]),

            "z_offset":
                int(best["z_offset"]),

            "dx":
                float(best["dx"]),

            "dy":
                float(best["dy"])

        })


best_df = pd.DataFrame(
    best_rows
)


# =============================================================================
# AUDIT-ONLY CLASSIFICATION
# =============================================================================

def classify_geometry(row):

    score = float(
        row["best_mean_Dice"]
    )

    margin = row["Dice_margin"]

    if (
        score >= 0.85
        and pd.notna(margin)
        and margin >= 0.15
    ):

        return "STRONG_GEOMETRIC_EVIDENCE"

    elif score >= 0.75:

        return "GOOD_GEOMETRIC_EVIDENCE"

    elif score >= 0.50:

        return "MODERATE_GEOMETRIC_EVIDENCE"

    else:

        return "WEAK_GEOMETRIC_EVIDENCE"


if not best_df.empty:

    best_df[
        "audit_classification"
    ] = best_df.apply(
        classify_geometry,
        axis=1
    )


best_df.to_csv(
    OUT_BEST_CSV,
    index=False
)


# =============================================================================
# FINAL REPORT
# =============================================================================

print("\n" + "=" * 80)
