def parse_shape(shape_string):

    try:
        return tuple(
            int(x.strip())
            for x in shape_string.strip(
                "()"
            ).split(",")
            if x.strip()
        )
    except Exception:
        return None


qc_df["parsed_shape"] = qc_df[
    "image_volume_shape"
].apply(parse_shape)

