print("-" * 80)

# Choose representative cases from different parts of dataset.
selected_indices = [
    0,
    len(df) // 4,
    len(df) // 2,
    (3 * len(df)) // 4,
    len(df) - 1
]

selected_indices = sorted(
    set(
        i for i in selected_indices
        if 0 <= i < len(df)
    )
)

for index in selected_indices:

    row = df.iloc[index]

    subset_id = str(
        row["subset_nodule_id"]
    )

    image_path = str(
        row["image_volume_path"]
    )

    if not os.path.exists(image_path):
        continue

    try:

        volume = np.load(
            image_path
        )

        # Pick the central slice.
        center = volume.shape[0] // 2

        image_slice = volume[
            center
        ]

        masks = []

        for mask_num in range(4):

            mask_col = (
                f"mask_{mask_num}_path"
            )

            if (
                mask_col in row.index
                and str(
                    row[mask_col]
                ).strip()
                and str(
                    row[mask_col]
                ).lower()
                != "nan"
                and os.path.exists(
                    str(row[mask_col])
                )
            ):

                mask_volume = np.load(
                    str(row[mask_col])
                )

                if (
                    center
                    < mask_volume.shape[0]
                ):

                    masks.append(
                        (
                            mask_num,
                            mask_volume[
                                center
                            ] > 0
                        )
                    )

        # -------------------------------------------------------------
        # Base image
        # -------------------------------------------------------------

        plt.figure(
            figsize=(7, 7)
        )

        plt.imshow(
            image_slice,
            cmap="gray"
        )

        # -------------------------------------------------------------
        # Overlay all available masks
        # -------------------------------------------------------------

        for mask_num, mask_slice in masks:

            overlay = np.ma.masked_where(
                ~mask_slice,
                mask_slice
            )

            plt.imshow(
                overlay,
                alpha=0.30
            )

        plt.title(
            f"{subset_id} | "
            f"{row['patient_id']} | "
            f"slice {center}"
        )

        plt.axis("off")

        plt.tight_layout()

        fig_path = os.path.join(
            QC_FIG_DIR,
            f"{subset_id}_overlay.png"
        )

        plt.savefig(
            fig_path,
            dpi=150,
            bbox_inches="tight"
        )

        plt.close()

        print(
            f"Saved: {fig_path}"
        )

    except Exception as e:

        print(
            f"WARNING: Could not generate "
            f"overlay for {subset_id}: {e}"
        )


