class LIDCNormalizedSliceDataset(Dataset):

    def __init__(self, dataframe):

        self.df = (
            dataframe
            .reset_index(drop=True)
            .copy()
        )

        # Cache normalized volumes so repeated slices from the same
        # nodule can be loaded efficiently.

        self.volume_cache = {}
        self.mask_cache = {}

    def __len__(self):

        total = 0

        for _, row in self.df.iterrows():

            volume_path = str(
                row["image_volume_path"]
            )

            if not os.path.exists(volume_path):
                raise FileNotFoundError(
                    f"Missing normalized volume: {volume_path}"
                )

            volume = np.load(
                volume_path,
                mmap_mode="r"
            )

            total += volume.shape[0]

        return total

    def _build_index(self):

        index = []

        for row_index, row in self.df.iterrows():

            volume_path = str(
                row["image_volume_path"]
            )

            volume = np.load(
                volume_path,
                mmap_mode="r"
            )

            for slice_index in range(
                volume.shape[0]
            ):

                index.append(
                    (
                        row_index,
                        slice_index
                    )
                )

        return index

    def _load_volume(self, path):

        if path not in self.volume_cache:

            volume = np.load(
                path
            ).astype(
                np.float32
            )

            self.volume_cache[path] = volume

        return self.volume_cache[path]

    def _load_mask_volume(
        self,
        path
    ):

        if not path:
            return None

        if path.lower() == "nan":
            return None

        if not os.path.exists(path):
            return None

        if path not in self.mask_cache:

            mask = np.load(
                path
            ).astype(
                np.float32
            )

            self.mask_cache[path] = mask

        return self.mask_cache[path]

    def __getitem__(self, index):

        if not hasattr(
            self,
            "_index"
        ):

            self._index = (
                self._build_index()
            )

        row_index, slice_index = (
            self._index[index]
        )

        row = self.df.iloc[
            row_index
        ]

        # -------------------------------------------------------------
        # Load normalized image volume
        # -------------------------------------------------------------

        volume_path = str(
            row["image_volume_path"]
        )

        volume = self._load_volume(
            volume_path
        )

        image = np.array(
            volume[slice_index],
            dtype=np.float32,
            copy=True
        )

        # -------------------------------------------------------------
        # Image sanity check
        # -------------------------------------------------------------

        if image.min() < -1e-5:
            raise ValueError(
                f"Image contains values < 0: "
                f"{image.min()}"
            )

        if image.max() > 1.00001:
            raise ValueError(
                f"Image contains values > 1: "
                f"{image.max()}"
            )

        image_tensor = torch.from_numpy(
            image.copy()
        ).unsqueeze(0)

        # -------------------------------------------------------------
        # Load masks
        # -------------------------------------------------------------

        masks = []

        for mask_num in range(4):

            path = str(
                row[
                    f"mask_{mask_num}_path"
                ]
            )

            mask_volume = (
                self._load_mask_volume(path)
            )

            if (
                mask_volume is not None
                and slice_index
                < mask_volume.shape[0]
            ):

                mask_slice = np.array(
                    mask_volume[slice_index],
                    dtype=np.float32,
                    copy=True
                )

            else:

                mask_slice = np.zeros(
                    image.shape,
                    dtype=np.float32
                )

            masks.append(
                torch.from_numpy(
                    mask_slice.copy()
                )
            )

        masks_tensor = torch.stack(
            masks,
            dim=0
        )

        return {

            "image":
                image_tensor,

            "masks":
                masks_tensor,

            "patient_id":
                str(row["patient_id"]),

            "subset_nodule_id":
                str(row["subset_nodule_id"]),

            "native_nodule_id":
                str(row["native_nodule_id"]),

            "SeriesInstanceUID":
                str(row["SeriesInstanceUID"]),

            "slice_index":
                int(slice_index),

            "split":
                str(row["split"]),

            # No malignancy target.
            "target":
                torch.tensor(
                    -1,
                    dtype=torch.long
                )

        }


