# =============================================================================
# U-NET
# =============================================================================

class DoubleConv(nn.Module):

    def __init__(
        self,
        in_channels,
        out_channels
    ):

        super().__init__()

        self.block = nn.Sequential(

            nn.Conv2d(
                in_channels,
                out_channels,
                kernel_size=3,
                padding=1,
                bias=False
            ),

            nn.BatchNorm2d(
                out_channels
            ),

            nn.ReLU(
                inplace=True
            ),

            nn.Conv2d(
                out_channels,
                out_channels,
                kernel_size=3,
                padding=1,
                bias=False
            ),

            nn.BatchNorm2d(
                out_channels
            ),

            nn.ReLU(
                inplace=True
            )

        )

    def forward(self, x):

        return self.block(x)


class UNet2D(nn.Module):

    def __init__(
        self,
        in_channels=1,
        out_channels=1
    ):

        super().__init__()

        self.enc1 = DoubleConv(
            in_channels,
            32
        )

        self.enc2 = DoubleConv(
            32,
            64
        )

        self.enc3 = DoubleConv(
            64,
            128
        )

        self.bottleneck = DoubleConv(
            128,
            256
        )

        self.pool = nn.MaxPool2d(
            kernel_size=2
        )

        self.up3 = nn.ConvTranspose2d(
            256,
            128,
            kernel_size=2,
            stride=2
        )

        self.dec3 = DoubleConv(
            256,
            128
        )

        self.up2 = nn.ConvTranspose2d(
            128,
            64,
            kernel_size=2,
            stride=2
        )

        self.dec2 = DoubleConv(
            128,
            64
        )

        self.up1 = nn.ConvTranspose2d(
            64,
            32,
            kernel_size=2,
            stride=2
        )

        self.dec1 = DoubleConv(
            64,
            32
        )

        self.out_conv = nn.Conv2d(
            32,
            out_channels,
            kernel_size=1
        )

    def forward(self, x):

        # Encoder
        e1 = self.enc1(x)

        e2 = self.enc2(
            self.pool(e1)
        )

        e3 = self.enc3(
            self.pool(e2)
        )

        b = self.bottleneck(
            self.pool(e3)
        )

        # Decoder
        d3 = self.up3(b)

        d3 = torch.cat(
            [d3, e3],
            dim=1
        )

        d3 = self.dec3(
            d3
        )

        d2 = self.up2(d3)

        d2 = torch.cat(
            [d2, e2],
            dim=1
        )

        d2 = self.dec2(
            d2
        )

        d1 = self.up1(d2)

        d1 = torch.cat(
            [d1, e1],
            dim=1
        )

        d1 = self.dec1(
            d1
        )

        return self.out_conv(d1)


# =============================================================================
# DICE LOSS
# =============================================================================

def dice_score(
    prediction,
    target,
    smooth=1e-6
):

    prediction = (
        torch.sigmoid(
            prediction
        )
        > 0.5
    ).float()

    intersection = (
        prediction
        * target
    ).sum(
        dim=(1, 2, 3)
    )

    denominator = (
        prediction.sum(
            dim=(1, 2, 3)
        )
        +
        target.sum(
            dim=(1, 2, 3)
        )
    )

    dice = (
        (2.0 * intersection + smooth)
        /
        (denominator + smooth)
    )

    return dice.mean()


def dice_loss(
    prediction,
    target,
    smooth=1e-6
):

    probabilities = torch.sigmoid(
        prediction
    )

    intersection = (
        probabilities
        * target
    ).sum(
        dim=(1, 2, 3)
    )

    denominator = (
        probabilities.sum(
            dim=(1, 2, 3)
        )
        +
        target.sum(
            dim=(1, 2, 3)
        )
    )

    dice = (
        (2.0 * intersection + smooth)
        /
        (denominator + smooth)
    )

    return (
        1.0
        - dice.mean()
    )


# =============================================================================
# MODEL
# =============================================================================

model = UNet2D().to(
    DEVICE
)

optimizer = torch.optim.Adam(
    model.parameters(),
    lr=1e-3
)

bce_loss = nn.BCEWithLogitsLoss()


def combined_loss(
    logits,
    target
):

    return (
        0.5 * bce_loss(
            logits,
            target
        )
        +
        0.5 * dice_loss(
            logits,
            target
        )
    )


# =============================================================================
# TRAINING FUNCTIONS
# =============================================================================

def train_one_epoch(
    model,
    loader,
    optimizer
):

    model.train()

    total_loss = 0.0
    total_dice = 0.0
    batches = 0

    for batch in loader:

        images = batch[
            "image"
        ].to(
            DEVICE,
            non_blocking=True
        )

        masks = batch[
            "mask"
        ].to(
            DEVICE,
            non_blocking=True
        )

        optimizer.zero_grad()

        logits = model(
            images
        )

        loss = combined_loss(
            logits,
            masks
        )

        loss.backward()

        optimizer.step()

        batch_dice = dice_score(
            logits.detach(),
            masks
        )

        total_loss += (
            loss.item()
        )

        total_dice += (
            batch_dice.item()
        )

        batches += 1

    return (
        total_loss / max(batches, 1),
        total_dice / max(batches, 1)
    )


@torch.no_grad()
def evaluate(
    model,
    loader
):

    model.eval()

    total_loss = 0.0
    total_dice = 0.0
    batches = 0

    for batch in loader:

        images = batch[
            "image"
        ].to(
            DEVICE,
            non_blocking=True
        )

        masks = batch[
            "mask"
        ].to(
            DEVICE,
            non_blocking=True
        )

        logits = model(
            images
        )

        loss = combined_loss(
            logits,
            masks
        )

        batch_dice = dice_score(
            logits,
            masks
        )

        total_loss += (
            loss.item()
        )

        total_dice += (
            batch_dice.item()
        )

        batches += 1

    return (
        total_loss / max(batches, 1),
        total_dice / max(batches, 1)
    )


