# -------------------------------------------------------------------------
# Detect columns robustly
# -------------------------------------------------------------------------

def find_column(df, candidates):

    lookup = {
        str(c).strip().lower(): c
        for c in df.columns
    }

    for candidate in candidates:

        key = candidate.strip().lower()

        if key in lookup:

            return lookup[key]

    return None


