# =============================================================================
# STEP 36 — ENHANCED IMAGE PREPROCESSING PIPELINE
# =============================================================================
#
# PURPOSE
# -------
# Create a new enhanced image dataset for a controlled comparison against:
#
#   1. Original images
#   2. Current processed images
#   3. Enhanced processed images
#
# IMAGE TRANSFORMATION
# --------------------
# For every image slice:
#
#   A. Convert to grayscale
#   B. Robust percentile windowing (1st -> 99th percentile)
#   C. Rescale to [0,255]
#   D. Apply CLAHE/local contrast enhancement
#   E. Save as PNG
#
# MASKS
# -----
# Masks are copied WITHOUT modification.
#
# IMPORTANT
# ---------
# This step creates a NEW dataset. It does not modify:
#
#   /content/kagl_lidc_idri.zip
#   /content/processed_325_nodules
#
# No malignancy labels are assigned.
# =============================================================================

import os
import shutil
import numpy as np
import pandas as pd
from PIL import Image, ImageOps, ImageEnhance

# Try OpenCV for CLAHE.
try:
    import cv2
    CV2_AVAILABLE = True
except ImportError:
    CV2_AVAILABLE = False

# =============================================================================
# 1. PATHS
# =============================================================================

ML_MANIFEST = "/content/final_325_ml_manifest.csv"

SOURCE_ROOT = "/content/processed_325_nodules"

ENHANCED_ROOT = "/content/enhanced_processed_325_nodules"

OUTPUT_MANIFEST = (
    "/content/enhanced_325_manifest.csv"
)

OUTPUT_QC = (
    "/content/step36_enhanced_preprocessing_qc.csv"
)

OUTPUT_SUMMARY = (
    "/content/step36_enhanced_preprocessing_summary.txt"
)

# =============================================================================
# 2. SETTINGS
# =============================================================================

LOW_PERCENTILE = 1.0
HIGH_PERCENTILE = 99.0

# CLAHE settings.
CLAHE_CLIP_LIMIT = 2.0
CLAHE_GRID_SIZE = (8, 8)

# Optional mild contrast multiplier after CLAHE.
# Keep this modest to avoid extreme enhancement.
CONTRAST_FACTOR = 1.05

print("=" * 80)
print("STEP 36 — ENHANCED IMAGE PREPROCESSING")
print("=" * 80)

print("\nTRANSFORMATION")
print("-" * 80)

print(
    f"Percentile window: "
    f"{LOW_PERCENTILE}% -> {HIGH_PERCENTILE}%"
)

print(
    f"CLAHE available: "
    f"{CV2_AVAILABLE}"
)

print(
    f"CLAHE clip limit: "
    f"{CLAHE_CLIP_LIMIT}"
)

print(
    f"CLAHE grid size: "
    f"{CLAHE_GRID_SIZE}"
)

# =============================================================================
# 3. INPUT VALIDATION
# =============================================================================

if not os.path.exists(ML_MANIFEST):

    raise FileNotFoundError(
        f"Missing ML manifest: {ML_MANIFEST}"
    )

if not os.path.isdir(SOURCE_ROOT):

    raise FileNotFoundError(
        f"Missing processed dataset: {SOURCE_ROOT}"
    )

manifest = pd.read_csv(
    ML_MANIFEST
)

assert len(manifest) == 325

assert (
    manifest[
        "subset_nodule_id"
    ].nunique()
    == 325
)

assert "nodule_029" not in set(
    manifest["subset_nodule_id"]
)

assert "nodule_085" not in set(
    manifest["subset_nodule_id"]
)

print("\nINPUT VALIDATION")
print("-" * 80)

print(
    f"Eligible nodules: "
    f"{len(manifest)}"
)

print(
    f"Patients: "
    f"{manifest['patient_id'].nunique()}"
)

print(
    "✓ 325-nodule cohort confirmed"
)

# =============================================================================
# 4. CREATE OUTPUT DIRECTORY
# =============================================================================

if os.path.exists(ENHANCED_ROOT):

    print(
        "\nExisting enhanced dataset found."
    )

    print(
        "Removing previous Step 36 output..."
    )

    shutil.rmtree(
        ENHANCED_ROOT
    )

os.makedirs(
    ENHANCED_ROOT,
    exist_ok=True
)

# =============================================================================
# 5. ENHANCEMENT FUNCTION
# =============================================================================

def enhance_image(image_array):
    """
    Deterministic per-slice enhancement.

    Steps:
        1. Convert to float32.
        2. Robust 1%-99% intensity clipping.
        3. Rescale to [0,255].
        4. Apply CLAHE if OpenCV is available.
        5. Apply mild contrast enhancement.
        6. Return uint8.
    """

    arr = np.asarray(
        image_array,
        dtype=np.float32
    )

    # -------------------------------------------------------------
    # Handle pathological images safely.
    # -------------------------------------------------------------

    if arr.size == 0:

        raise ValueError(
            "Empty image encountered."
        )

    # -------------------------------------------------------------
    # Robust percentile limits.
    # -------------------------------------------------------------

    low = np.percentile(
        arr,
        LOW_PERCENTILE
    )

    high = np.percentile(
        arr,
        HIGH_PERCENTILE
    )

    # Prevent zero-width window.
    if high <= low:

        low = float(
            arr.min()
        )

        high = float(
            arr.max()
        )

    # -------------------------------------------------------------
    # Constant image fallback.
    # -------------------------------------------------------------

    if high <= low:

        enhanced = np.zeros_like(
            arr,
            dtype=np.uint8
        )

        return enhanced

    # -------------------------------------------------------------
    # Clip and normalize to 0-255.
    # -------------------------------------------------------------

    clipped = np.clip(
        arr,
        low,
        high
    )

    normalized = (
        (clipped - low)
        /
        (high - low)
        *
        255.0
    )

    normalized = np.clip(
        normalized,
        0,
        255
    ).astype(
        np.uint8
    )

    # -------------------------------------------------------------
    # CLAHE local contrast enhancement.
    # -------------------------------------------------------------

    if CV2_AVAILABLE:

        clahe = cv2.createCLAHE(
            clipLimit=CLAHE_CLIP_LIMIT,
            tileGridSize=CLAHE_GRID_SIZE
        )

        enhanced = clahe.apply(
            normalized
        )

    else:

        # Fallback using PIL autocontrast.
        pil_img = Image.fromarray(
            normalized,
            mode="L"
        )

        pil_img = ImageOps.autocontrast(
            pil_img
        )

        enhanced = np.asarray(
            pil_img,
            dtype=np.uint8
        )

    # -------------------------------------------------------------
    # Mild final contrast adjustment.
    # -------------------------------------------------------------

    if CONTRAST_FACTOR != 1.0:

        pil_img = Image.fromarray(
            enhanced,
            mode="L"
        )

        enhancer = ImageEnhance.Contrast(
            pil_img
        )

        pil_img = enhancer.enhance(
            CONTRAST_FACTOR
        )

        enhanced = np.asarray(
            pil_img,
            dtype=np.uint8
        )

    return enhanced


# =============================================================================
# 6. PROCESS ALL 325 NODULES
# =============================================================================

qc_rows = []

total_images = 0
successful_images = 0
failed_images = 0

print("\nPROCESSING ENHANCED IMAGES")
print("-" * 80)

for counter, (_, row) in enumerate(
    manifest.iterrows(),
    start=1
):

    subset_id = str(
        row[
            "subset_nodule_id"
        ]
    ).strip()

    patient_id = str(
        row[
            "patient_id"
        ]
    ).strip()

    native_id = str(
        row[
            "native_nodule_id"
        ]
    ).strip()

    split = str(
        row[
            "split"
        ]
    ).strip().lower()

    source_case_dir = os.path.join(
        SOURCE_ROOT,
        subset_id
    )

    source_image_dir = os.path.join(
        source_case_dir,
        "images"
    )

    output_case_dir = os.path.join(
        ENHANCED_ROOT,
        subset_id
    )

    output_image_dir = os.path.join(
        output_case_dir,
        "images"
    )

    os.makedirs(
        output_image_dir,
        exist_ok=True
    )

    if not os.path.isdir(
        source_image_dir
    ):

        raise FileNotFoundError(
            f"Missing source image directory: "
            f"{source_image_dir}"
        )

    source_images = [

        f
        for f in os.listdir(
            source_image_dir
        )
        if f.lower().endswith(".png")

    ]

    def numeric_sort(filename):

        digits = "".join(
            c
            for c in filename
            if c.isdigit()
        )

        return (
            int(digits)
            if digits
            else 0,
            filename
        )

    source_images = sorted(
        source_images,
        key=numeric_sort
    )

    image_success = 0

    image_failure = 0

    original_values = []
    enhanced_values = []

    for image_name in source_images:

        source_path = os.path.join(
            source_image_dir,
            image_name
        )

        output_path = os.path.join(
            output_image_dir,
            image_name
        )

        try:

            with Image.open(
                source_path
            ) as img:

                original = np.asarray(
                    img.convert("L"),
                    dtype=np.float32
                )

            enhanced = enhance_image(
                original
            )

            Image.fromarray(
                enhanced,
                mode="L"
            ).save(
                output_path
            )

            # ---------------------------------------------------------
            # Track statistics.
            # ---------------------------------------------------------

            original_values.extend(
                [
                    float(original.min()),
                    float(original.max()),
                    float(original.mean())
                ]
            )

            enhanced_values.extend(
                [
                    float(enhanced.min()),
                    float(enhanced.max()),
                    float(enhanced.mean())
                ]
            )

            image_success += 1

            total_images += 1
            successful_images += 1

        except Exception as e:

            print(
                f"ERROR: {subset_id} / "
                f"{image_name}: {e}"
            )

            image_failure += 1
            total_images += 1
            failed_images += 1

    # -----------------------------------------------------------------
    # Copy masks WITHOUT modification.
    # -----------------------------------------------------------------

    mask_counts = {}

    for mask_num in range(4):

        source_mask_dir = os.path.join(
            source_case_dir,
            f"mask-{mask_num}"
        )

        output_mask_dir = os.path.join(
            output_case_dir,
            f"mask-{mask_num}"
        )

        mask_counts[
            mask_num
        ] = 0

        if not os.path.isdir(
            source_mask_dir
        ):

            continue

        os.makedirs(
            output_mask_dir,
            exist_ok=True
        )

        mask_files = [

            f
            for f in os.listdir(
                source_mask_dir
            )
            if f.lower().endswith(".png")

        ]

        mask_files = sorted(
            mask_files,
            key=numeric_sort
        )

        for mask_name in mask_files:

            source_mask = os.path.join(
                source_mask_dir,
                mask_name
            )

            output_mask = os.path.join(
                output_mask_dir,
                mask_name
            )

            shutil.copy2(
                source_mask,
                output_mask
            )

            mask_counts[
                mask_num
            ] += 1

    # -----------------------------------------------------------------
    # Case-level QC.
    # -----------------------------------------------------------------

    output_images = [

        f
        for f in os.listdir(
            output_image_dir
        )
        if f.lower().endswith(".png")

    ]

    output_images = sorted(
        output_images,
        key=numeric_sort
    )

    image_dimensions_consistent = True

    reference_dimensions = None

    for filename in output_images:

        path = os.path.join(
            output_image_dir,
            filename
        )

        try:

            with Image.open(path) as img:

                dims = tuple(
                    img.size
                )

            if reference_dimensions is None:

                reference_dimensions = dims

            elif dims != reference_dimensions:

                image_dimensions_consistent = False

        except Exception:

            image_dimensions_consistent = False

    masks_preserved = True

    for mask_num in range(4):

        source_mask_dir = os.path.join(
            source_case_dir,
            f"mask-{mask_num}"
        )

        output_mask_dir = os.path.join(
            output_case_dir,
            f"mask-{mask_num}"
        )

        if not os.path.isdir(
            source_mask_dir
        ):

            continue

        source_count = len([
            f
            for f in os.listdir(
                source_mask_dir
            )
            if f.lower().endswith(".png")
        ])

        output_count = len([
            f
            for f in os.listdir(
                output_mask_dir
            )
            if f.lower().endswith(".png")
        ])

        if source_count != output_count:

            masks_preserved = False

    case_pass = (
        image_failure == 0
        and
        len(output_images)
        ==
        len(source_images)
        and
        image_dimensions_consistent
        and
        masks_preserved
    )

    qc_rows.append({

        "subset_nodule_id":
            subset_id,

        "patient_id":
            patient_id,

        "native_nodule_id":
            native_id,

        "split":
            split,

        "source_image_count":
            len(source_images),

        "enhanced_image_count":
            len(output_images),

        "image_failures":
            image_failure,

        "output_image_dimensions":
            str(reference_dimensions),

        "image_dimensions_consistent":
            image_dimensions_consistent,

        "mask_0_count":
            mask_counts[0],

        "mask_1_count":
            mask_counts[1],

        "mask_2_count":
            mask_counts[2],

        "mask_3_count":
            mask_counts[3],

        "masks_preserved":
            masks_preserved,

        "enhanced_case_qc":
            "PASS"
            if case_pass
            else "FAIL"

    })

    if counter % 25 == 0:

        print(
            f"Processed "
            f"{counter} / {len(manifest)}"
        )


# =============================================================================
# 7. SAVE QC TABLE
# =============================================================================

qc_df = pd.DataFrame(
    qc_rows
)

qc_df.to_csv(
    OUTPUT_QC,
    index=False
)

# =============================================================================
# 8. FINAL VALIDATION
# =============================================================================

passed_cases = int(
    (
        qc_df[
            "enhanced_case_qc"
        ]
        == "PASS"
    ).sum()
)

failed_cases = (
    len(qc_df)
    -
    passed_cases
)

print("\n" + "=" * 80)
print("STEP 36 RESULTS")
print("=" * 80)

print(
    f"\nNodules processed: "
    f"{len(qc_df)}"
)

print(
    f"Images processed: "
    f"{total_images}"
)

print(
    f"Images successfully enhanced: "
    f"{successful_images}"
)

print(
    f"Image processing failures: "
    f"{failed_images}"
)

print(
    f"Cases passing enhancement QC: "
    f"{passed_cases} / 325"
)

print(
    f"Cases failing enhancement QC: "
    f"{failed_cases} / 325"
)

assert len(qc_df) == 325

assert (
    qc_df[
        "subset_nodule_id"
    ].nunique()
    == 325
)

assert failed_cases == 0

print(
    "✓ All 325 enhanced cases passed QC."
)

# =============================================================================
# 9. VERIFY MASKS WERE PRESERVED
# =============================================================================

print("\nMASK PRESERVATION")
print("-" * 80)

mask_failures = int(
    (
        ~qc_df[
            "masks_preserved"
        ]
    ).sum()
)

print(
    f"Cases with mask-copy discrepancies: "
    f"{mask_failures}"
)

assert mask_failures == 0

print(
    "✓ Mask files preserved without modification."
)

# =============================================================================
# 10. VERIFY IMAGE RANGE
# =============================================================================

print("\nENHANCED IMAGE RANGE CHECK")
print("-" * 80)

range_failures = 0

for counter, (_, row) in enumerate(
    manifest.iterrows(),
    start=1
):

    subset_id = str(
        row[
            "subset_nodule_id"
        ]
    )

    image_dir = os.path.join(
        ENHANCED_ROOT,
        subset_id,
        "images"
    )

    files = [
        f
        for f in os.listdir(
            image_dir
        )
        if f.lower().endswith(".png")
    ]

    for filename in files:

        path = os.path.join(
            image_dir,
            filename
        )

        with Image.open(path) as img:

            arr = np.asarray(
                img.convert("L"),
                dtype=np.uint8
            )

        if (
            arr.min() < 0
            or
            arr.max() > 255
        ):

            range_failures += 1

    if counter % 50 == 0:

        print(
            f"Checked "
            f"{counter} / {len(manifest)}"
        )

print(
    f"Range failures: "
    f"{range_failures}"
)

assert range_failures == 0

print(
    "✓ All enhanced images are valid uint8 PNGs."
)

# =============================================================================
# 11. CREATE ENHANCED MANIFEST
# =============================================================================

enhanced_manifest = manifest.copy()

enhanced_manifest[
    "enhanced_dataset_root"
] = ENHANCED_ROOT

enhanced_manifest[
    "enhanced_image_directory"
] = enhanced_manifest[
    "subset_nodule_id"
].apply(
    lambda x: os.path.join(
        ENHANCED_ROOT,
        str(x),
        "images"
    )
)

enhanced_manifest[
    "preprocessing_method"
] = (
    "1%-99% percentile clipping + "
    "rescaling + CLAHE + mild contrast"
)

enhanced_manifest[
    "preprocessing_original_pixels_preserved"
] = False

enhanced_manifest[
    "masks_modified"
] = False

enhanced_manifest[
    "malignancy_labels_assigned"
] = False

enhanced_manifest[
    "native_to_xml_identity_proven"
] = False

enhanced_manifest.to_csv(
    os.path.join(
        ENHANCED_ROOT,
        "enhanced_manifest.csv"
    ),
    index=False
)

# Also save to /content.
enhanced_manifest.to_csv(
    OUTPUT_MANIFEST,
    index=False
)

# =============================================================================
# 12. SUMMARY
# =============================================================================

summary = f"""
===============================================================================
STEP 36 — ENHANCED PREPROCESSING SUMMARY
===============================================================================

COHORT
-------------------------------------------------------------------------------
Eligible nodules:                  {len(manifest)}
Unique patients:                   {manifest['patient_id'].nunique()}

IMAGE PROCESSING
-------------------------------------------------------------------------------
Images processed:                  {total_images}
Images successfully enhanced:      {successful_images}
Image processing failures:         {failed_images}

Cases passing enhancement QC:      {passed_cases} / 325
Cases failing enhancement QC:      {failed_cases} / 325

PREPROCESSING
-------------------------------------------------------------------------------
Intensity window:
    {LOW_PERCENTILE}% -> {HIGH_PERCENTILE}% percentile

CLAHE:
    {'YES' if CV2_AVAILABLE else 'NO — PIL fallback used'}

CLAHE clip limit:
    {CLAHE_CLIP_LIMIT}

CLAHE grid:
    {CLAHE_GRID_SIZE}

Final contrast factor:
    {CONTRAST_FACTOR}

MASKS
-------------------------------------------------------------------------------
Masks modified:                    NO
Mask-copy discrepancies:           {mask_failures}

PROVENANCE
-------------------------------------------------------------------------------
Native-to-XML identity established: NO
Native malignancy labels assigned:  NO

IMPORTANT
-------------------------------------------------------------------------------
This enhanced dataset is intended for a controlled experimental comparison
against the original and current processed datasets.

The enhancement changes image intensity representation and local contrast.
Therefore it is NOT pixel-equivalent to the original dataset.

Validation and test images receive the same deterministic preprocessing but
NO augmentation is applied.

Training augmentation, if used later, should be applied only during training
inside the DataLoader rather than permanently modifying validation/test data.

OUTPUTS
-------------------------------------------------------------------------------
Enhanced dataset:
    {ENHANCED_ROOT}

Enhanced manifest:
    {OUTPUT_MANIFEST}

QC:
    {OUTPUT_QC}

Summary:
    {OUTPUT_SUMMARY}

===============================================================================
"""

with open(
    OUTPUT_SUMMARY,
    "w"
) as f:

    f.write(
        summary.strip()
    )

print(
    "\n" + summary
)

