def natural_sort(paths):

    def key(path):

        filename = os.path.basename(
            path
        )

        parts = re.split(
            r"(\d+)",
            filename
        )

        result = []

        for part in parts:

            if part.isdigit():

                result.append(
                    (
                        0,
                        int(part)
                    )
                )

            else:

                result.append(
                    (
                        1,
                        part
                    )
                )

        return result

    return sorted(
        paths,
        key=key
    )


