# =============================================================================
# 11. LOAD CONSENSUS MASKS
# =============================================================================
#
# Same masks used for all three conditions.
#
# Majority vote across the four native mask directories.
# =============================================================================

print("\nBUILDING CONSENSUS MASKS")
print("-" * 80)

mask_lookup = {}

for counter, (_, row) in enumerate(
    manifest.iterrows(),
    start=1
):

    subset_id = row[
        "subset_nodule_id"
    ]

    case_dir = os.path.join(
        CURRENT_PROCESSED_ROOT,
        subset_id
    )

    reader_volumes = []

    for reader in range(4):

        mask_dir = os.path.join(
            case_dir,
            f"mask-{reader}"
        )

        if not os.path.isdir(
            mask_dir
        ):

            continue

        files = [
            os.path.join(
                mask_dir,
                f
            )
            for f in os.listdir(
                mask_dir
            )
            if f.lower().endswith(".png")
        ]

        files = natural_sort(
            files
        )

        # Load mask files.
        slices = []

        for path in files:

            with Image.open(
                path
            ) as img:

                arr = np.asarray(
                    img.convert("L"),
                    dtype=np.uint8
                )

            slices.append(
                arr > 0
            )

        if not slices:
            continue

        volume = np.stack(
            slices,
            axis=0
        )

        reader_volumes.append(
            volume
        )

    if not reader_volumes:

        raise RuntimeError(
            f"No masks found for {subset_id}"
        )

    # -------------------------------------------------------------
    # Handle different reader depths safely.
    # -------------------------------------------------------------

    max_depth = max(
        v.shape[0]
        for v in reader_volumes
    )

    reference_h = reader_volumes[
        0
    ].shape[1]

    reference_w = reader_volumes[
        0
    ].shape[2]

    consensus_slices = []

    for z in range(
        max_depth
    ):

        available = []

        for volume in reader_volumes:

            if z < volume.shape[0]:

                available.append(
                    volume[z]
                )

        if not available:
            continue

        # All masks should have same H/W.
        for arr in available:

            if arr.shape != (
                reference_h,
                reference_w
            ):

                raise ValueError(
                    f"Mask dimension mismatch "
                    f"for {subset_id}"
                )

        stacked = np.stack(
            available,
            axis=0
        )

        consensus = (
            stacked.mean(
                axis=0
            )
            >= 0.5
        )

        consensus_slices.append(
            consensus
        )

    mask_lookup[
        subset_id
    ] = np.stack(
        consensus_slices,
        axis=0
    )

    if counter % 25 == 0:

        print(
            f"Consensus masks: "
            f"{counter} / 325"
        )

print(
    f"Consensus masks created: "
    f"{len(mask_lookup)} / 325"
)

