# =============================================================================
# 13. DATASET CLASS
# =============================================================================

class ThreeWayDataset(
    Dataset
):

    def __init__(
        self,
        dataframe,
        condition
    ):

        self.df = (
            dataframe
            .reset_index(
                drop=True
            )
        )

        self.condition = condition

    def __len__(self):

        return len(
            self.df
        )

    def __getitem__(
        self,
        index
    ):

        row = self.df.iloc[
            index
        ]

        subset_id = str(
            row[
                "subset_nodule_id"
            ]
        )

        z = int(
            row[
                "slice_index"
            ]
        )

        # -------------------------------------------------------------
        # Load selected image source.
        # -------------------------------------------------------------

        if self.condition == "original":

            zip_path = (
                original_lookup[
                    subset_id
                ][z]
            )

            with zip_file.open(
                zip_path
            ) as f:

                data = f.read()

            with Image.open(
                io.BytesIO(data)
            ) as img:

                image = np.asarray(
                    img.convert("L"),
                    dtype=np.float32
                )

        elif self.condition == "current_processed":

            path = (
                current_lookup[
                    subset_id
                ][z]
            )

            with Image.open(
                path
            ) as img:

                image = np.asarray(
                    img.convert("L"),
                    dtype=np.float32
                )

        elif self.condition == "enhanced_processed":

            path = (
                enhanced_lookup[
                    subset_id
                ][z]
            )

            with Image.open(
                path
            ) as img:

                image = np.asarray(
                    img.convert("L"),
                    dtype=np.float32
                )

        else:

            raise ValueError(
                f"Unknown condition: "
                f"{self.condition}"
            )

        # -------------------------------------------------------------
        # IDENTICAL NORMALIZATION FOR ALL CONDITIONS
        # -------------------------------------------------------------
        #
        # This is intentionally performed at load time.
        #
        # This makes the benchmark fair: the model sees values in [0,1]
        # under the same normalization operation for all three conditions.
        # -------------------------------------------------------------

        image_min = float(
            image.min()
        )

        image_max = float(
            image.max()
        )

        if image_max > image_min:

            image = (
                image - image_min
            ) / (
                image_max - image_min
            )

        else:

            image = np.zeros_like(
                image,
                dtype=np.float32
            )

        # -------------------------------------------------------------
        # Consensus mask
        # -------------------------------------------------------------

        mask = (
            mask_lookup[
                subset_id
            ][z]
            .astype(np.float32)
        )

        image_tensor = torch.from_numpy(
            image.copy()
        ).unsqueeze(0).float()

        mask_tensor = torch.from_numpy(
            mask.copy()
        ).unsqueeze(0).float()

        return (
            image_tensor,
            mask_tensor
        )


